 void releaseResources() override {} void processBlock(juce::AudioBuffer<float>& b,juce::MidiBuffer&) override {juce::ScopedNoDenormals no; const int cpu=(int)v("CPU mode"); if(previousMode!=cpu){if(cpu==2){for(auto& e:maxEngines)e.reset();}else if(previousMode==2){for(auto& e:engines)e.reset();}previousMode=cpu;} for(int ch=0;ch<b.getNumChannels();++ch){auto render=[&](auto& e){ auto& c=e.controls; const decltype(c.preamp) models[]={decltype(c.preamp)::Jose,decltype(c.preamp)::Peavey5150,decltype(c.preamp)::DualRectifier,decltype(c.preamp)::VHT,decltype(c.preamp)::EVH5150III}; const decltype(c.joseArchitecture) arch[]={decltype(c.joseArchitecture)::Stock,decltype(c.joseArchitecture)::Classic,decltype(c.joseArchitecture)::HBE,decltype(c.joseArchitecture)::Snorkler,decltype(c.joseArchitecture)::JosePostEQ,decltype(c.joseArchitecture)::Molecular}; c.preamp=models[(int)v("Amp")];c.joseArchitecture=arch[(int)v("Marshall")];{const int a=(int)v("Recto architecture"),ch=(int)v("Recto channel"),m=(int)v("Recto voicing");const decltype(c.rectoVoice) voices[3][2][2]={{{decltype(c.rectoVoice)::EarlyOrange,decltype(c.rectoVoice)::EarlyOrangeModern},{decltype(c.rectoVoice)::EarlyRedVintage,decltype(c.rectoVoice)::EarlyRed}},{{decltype(c.rectoVoice)::MultiOrangeVintage,decltype(c.rectoVoice)::MultiOrangeModern},{decltype(c.rectoVoice)::MultiRedVintage,decltype(c.rectoVoice)::MultiWattModern}},{{decltype(c.rectoVoice)::RoadKing3Vintage,decltype(c.rectoVoice)::RoadKing3Modern},{decltype(c.rectoVoice)::RoadKing4Vintage,decltype(c.rectoVoice)::RoadKing4Modern}}};c.rectoVoice=voices[a][ch][m];}c.evhVoice=(decltype(c.evhVoice))(int)v("EVH");c.linkPower=v("Link power")>.5f;c.power=(decltype(c.power))(int)v("Power amp");c.autoTube=(int)v("Tube")==3;c.tube=(decltype(c.tube))juce::jlimit(0,2,(int)v("Tube"));c.coldBias=c.joseBias=(decltype(c.coldBias))(int)v("Cold bias");c.coldBypass=c.joseBypass=(decltype(c.coldBypass))(int)v("Bypass cap");c.joseEra=(decltype(c.joseEra))(int)v("Jose clip");c.volume=v("Volume");c.brightMode=(int)v("Bright cap");c.josePostEQ=(int)v("Clip position")==1;c.joseSAT=(int)v("Marshall")==2||(int)v("Marshall")==3||(int)v("Marshall")==5;c.eco=cpu==1;c.disableFeedback=(int)v("Signal check")==3;c.inverterOnly=(int)v("Signal check")==4;c.gain=v("Gain");c.joseGain2=v("Gain 2");c.bass=v("Bass");c.mid=v("Mid");c.treble=v("Treble");c.presence=v("Presence");c.master=v("Master");c.spongy=v("Spongy")>.5;c.tubeRect=v("Tube rectifier")>.5;auto* x=b.getWritePointer(ch);const auto mode=(int)v("Signal check");for(int i=0;i<b.getNumSamples();++i){ auto y=mode==1?x[i]:(mode==2?e.processPreampOnly(x[i]):e.process(x[i]));x[i]=std::isfinite(y)?(float)y:0.f;}};if(cpu==2)render(maxEngines[(size_t)ch]);else render(engines[(size_t)ch]);} if(v("Cabinet")>.5){juce::dsp::AudioBlock<float> block(b);cab.process(juce::dsp::ProcessContextReplacing<float>(block));}b.applyGain(juce::Decibels::decibelsToGain((v("Output")-.5f)*48.f));}
