 remove.onClick=[this]{int i=browser.getSelectedItemIndex();if(!juce::isPositiveAndBelow(i,files.size()))return;auto file=files[i];juce::Component::SafePointer<Editor> safe(this);juce::AlertWindow::showOkCancelBox(juce::MessageBoxIconType::WarningIcon,"Delete IR","Remove "+file.getFileName()+" from the library? Projects retain embedded IR data.","Delete","Cancel",this,juce::ModalCallbackFunction::create([safe,file](int result){if(safe!=nullptr&&result){file.deleteFile();safe->refresh();}}));};
