 void updateGraph(){spectrum.clear();if(p.irData.getSize()){juce::AudioFormatManager fm;fm.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader> reader(fm.createReaderFor(std::make_unique<juce::MemoryInputStream>(p.irData,true)));if(reader){constexpr int n=32768;juce::AudioBuffer<float> b(1,n);b.clear();reader->read(&b,0,(int)juce::jmin((juce::int64)n,reader->lengthInSamples),0,true,false);std::vector<float> fft(2*n,0);std::copy_n(b.getReadPointer(0),n,fft.data());juce::dsp::FFT transform(15);transform.performFrequencyOnlyForwardTransform(fft.data());spectrum.assign(fft.begin(),fft.begin()+n/2);graphRate=reader->sampleRate;}}repaint();}
