 void paint(juce::Graphics& g) override {g.fillAll(juce::Colour(0xff171b20));g.setColour(juce::Colour(0xffe2b77b));g.setFont(24.f);g.drawText("ULTIMATE HIGH GAIN",20,8,getWidth()-40,40,juce::Justification::centredLeft);g.setFont(14.f);if(cabinetPage){auto area=juce::Rectangle<float>(55,190,(float)getWidth()-90,(float)getHeight()-245);g.setColour(juce::Colour(0xff101418));g.fillRect(area);g.setColour(juce::Colours::grey);for(int db=0;db>=-60;db-=10){float y=area.getY()-db*area.getHeight()/60;g.drawHorizontalLine((int)y,area.getX(),area.getRight());g.drawText(juce::String(db),10,(int)y-8,40,16,juce::Justification::centredRight);}for(int f:{20,50,100,200,500,1000,2000,5000,10000,20000}){float x=area.getX()+area.getWidth()*(float)(std::log10(f/20.)/3.);g.drawVerticalLine((int)x,area.getY(),area.getBottom());g.drawText(juce::String(f),(int)x-20,(int)area.getBottom()+4,40,18,juce::Justification::centred);}if(!spectrum.empty()){float peak=*std::max_element(spectrum.begin(),spectrum.end());juce::Path path;for(int i=0;i<(int)area.getWidth();++i){double f=20*std::pow(1000.,i/area.getWidth());double bin=f*32768/graphRate;if(bin>=spectrum.size()-1)break;int k=(int)bin;float mag=spectrum[k]+(spectrum[k+1]-spectrum[k])*(float)(bin-k);float db=juce::Decibels::gainToDecibels(mag/std::max(peak,1e-12f),-60.f);float y=area.getY()-juce::jlimit(-60.f,0.f,db)*area.getHeight()/60;if(i==0)path.startNewSubPath(area.getX()+i,y);else path.lineTo(area.getX()+i,y);}g.setColour(juce::Colour(0xffe2b77b));g.strokePath(path,juce::PathStrokeType(1.5f));}g.drawText(p.irName,20,115,getWidth()-220,30,juce::Justification::centredLeft);return;}for(auto item:std::array<std::pair<int,const char*>,3>{{{58,"PREAMP / VOICING"},{300,"POWER AMP"},{482,"ENGINE"}}})g.drawText(item.second,20,item.first,getWidth()-40,22,juce::Justification::centredLeft);}
